svg.script:
// Optional helper: call setPawLevel(1, "1") etc. from SVG-hosting code.
function setPawLevel(level, value) {
  const text = document.getElementById("level-text-" + String(level).padStart(2, "0"));
  if (text) text.textContent = value == null ? "" : String(value);
}

// Returns the embedded GeoJSON FeatureCollection for all 45 level slots.
function getPawLevelGeoJSON() {
  const raw = document.getElementById("level-slot-geojson").textContent.trim();
  return JSON.parse(raw);
}
